import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"西溪易说卷十","description":"西溪易说 - 西溪易说卷十","frontmatter":{"title":"西溪易说卷十","description":"西溪易说 - 西溪易说卷十"},"headers":[],"relativePath":"zh/classics/xixi/011.md","filePath":"zh/classics/xixi/011.md"}'),i={name:"zh/classics/xixi/011.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易说卷十" tabindex="-1">西溪易说卷十 <a class="header-anchor" href="#西溪易说卷十" aria-label="Permalink to “西溪易说卷十”">​</a></h1><p>钦定四库全书</p><p>宋李过撰</p><p>䷭ 巽下坤上</p><p>升。</p><p>升：元亨。用见大人，勿恤，南征吉。象曰：柔以时升，巽而顺，刚中而应，是以大亨。「用见大人，勿恤」，有庆也。「南征吉」，志行也。坤上巽下，木生地中，自下升上之义。古之贤者升进于上，其道不一。有自司徒命卿论秀而升者；自司徒升之司乐，乐正升之司马，司马升之王所；有自侯方岁贡而升者，天子则试之射宫，中多者得与于祭。有自三年大比，因贤能之书而升者，天子拜受，登于天府。古者进升之道，大略如此。其条目纤悉，见于周官之职掌，与王制所载，而其义则隐于易之「升」。盖木之升也，其勾末萌甲未拆之时，枝柯干叶皆备于未升之时。及其得地，故其升也莫能御。犹贤者方其未进也，道德蓄蓄，皆当素备，故一出而名实遂孚矣。卦辞：升：元亨。君子之升，大亨之道也。用见大人，勿恤。大人，九五也。升而至五，则见君矣，宜无爱也。自巽至坤，皆离位也，故「南征吉」。象曰：「柔以时升。」谓初六柔自下而升，九二刚得中，六五在上，为己之应，是以「大亨」也。得见大人，则「有庆」矣，故无忧也。卦属南方，「离」明，万物相见，木道至此，其志乃行，故曰：「南征吉，志行也。」象曰：地中生木，「升」；君子以顺德，积小以高大。</p><p>「地中生木」，以渐而升。君子之升，不能遽进也，体二象之顺，积小以高大。盖「坤」以顺为德，「巽」亦以顺为德也。古人进身自有次第，不容躐等。</p><p>初六：允升，大吉。象曰：「允升大吉」，上合志也。</p><p>允，信也。初在下，犹其未升也，须诚实充足，然后进而大吉。故贤者之未升，必其行懋于家，德信于乡，然后可以论进。此自卿大夫而升，命乡论秀而升，皆自下推泽而进也。象曰「上合志也」，谓上合六五之志也。</p><p>九二：孚乃利用礿，无咎。象曰：九二之孚，有喜也。</p><p>进而至二，五为正应，潜德之孚于君矣，故宜用礿，不必其礼文之备也。此不由三道而升，自以德孚于君，是以为不次之升。如傅说之于高宗，以梦而升是也；太公之于文王，以卜而升是也。象曰「有喜也」，君臣相孚，故「有喜」也。</p><p>九三：升虚邑。象曰：「升虚邑」，无所疑也。又进至三，三，诸侯之位；邑，国也。进而至此，则一国皆推其善士矣，又何疑焉！此自侯国而升也，故曰「升虚邑」。象曰「无所疑也」，谓德孚于邑国，可以无疑也。</p><p>六四，王用享于岐山，吉，无咎。象曰：「王用享于岐山」，顺事也。</p><p>四，卿位，至此所谓升之司马，将论以进于王也。王，即六五也；岐山，西山也。此互体兑之上，故曰「岐山」。言六五之王，将论定而官之，是「享于岐山」也，象曰「顺事也」。进而至此，既得卦体，故曰「顺事」。</p><p>六五，贞吉，升阶。象曰：「贞吉升阶」，大得志也。</p><p>至此则进于天子之阶矣。或升之王，或试之射宫，或登之天府，皆所谓「升阶」也，则升道亨矣，故曰「贞吉」，象曰「大得志也」。升而至阶，得志可知也。</p><p>上六，置升，利于不息之贞。象曰：「置升」在上，消不富也。处升之极，知进而不知退，则颠置乎利达者也。君子知进退存亡，故宜贞守，贞守乃所以不息也。犹如木升之极，必归根复命，虽华实剥落，而生生之意又寓于其中矣，所谓「利不息之贞」也。象曰：冥升在上，消不富也。升极则反，其道消矣。以柔居之，故曰「不富」。䷮ 坎下兖上</p><p>困</p><p>困：亨。贞大人吉，无咎，有言不信。彖曰：「困」，刚揜也。险以说，困而不失其所亨，其惟君子乎？「贞，大人吉」，以刚中也。「有言不信」，尚口乃穷也。</p><p>困，刚揜也。三阳处三阴之间，阳为阴所揜，是君子为小人所困也。然困而亨，盖惟君子为能处困，身处困而道未尝不亨也。「贞大人吉」，谓九五也。九五谓困之主，举小人而去之，则君子之道亨而得「贞吉」矣。「有言不信」，君子处困，正当自守，难以口舌辨也。彖：困，刚揜也。刚为阴所揜也。卦坎险而兑说，险难而以说处之，困而不失其所亨，用此道也。此惟君子能之，被兵于匡、宋，绝粮于陈、蔡，而道未尝少贬，皆圣人事也。九五以刚居中，能困亨者也，故曰「以刚中也」。处困之时，逊言以避祸，故尚口乃穷也。六爻之义，圣人却有深意。据君子为小人所困，阳爻为君子，阴爻为小人，则阳爻当困，而阴爻当吉。然圣人设义，初为阴爻，「困于株木」；三为阴爻，「困于疾藜」；上为阴爻，「困于葛藟」。三阴爻皆凶。九二虽困，乃「朱绂方来」；九四虽渊，其终反吉。九五虽困，「乃徐有说」；三阳爻反吉，以见小人之困君子，君子终不可困，而小人实自困也。自古小人之困君子，未有不自败者。圣人设此义以防民，而后世小人犹有无忌惮者。</p><p>象曰：泽无水，困。君子以致命遂志。</p><p>君子处困之道固如此。</p><p>初六：臀困于株木，入于幽谷，三岁不觌。象曰：「入于幽谷」，幽不明也。</p><p>初与四为正应，四，君子也。今有困君子之意，故为九四所绝。四处互体「巽」，「巽」为木，初欲托庇于其下，已不能矣，故「困于株木」。自处「坎」之下，「坎」，北方，幽都也，故曰「入于幽谷」。越三爻而求九四，不能觌，言为君子所弃也。象曰「幽不明也」。</p><p>九二，困于酒食，朱绂方来，利用享祀。征凶，无咎。象曰：「困于酒食」，中有庆也。</p><p>二处「坎」中，「坎」为酒食，上下为同体二阴所困，所困特饮食，言所困之者小也。「朱绂」，君之服，谓九五也。诗曰：「朱绂斯皇，室家君王。」言九五将以同德来相求也，故曰「方来」。君臣同德，则可以受福，故「利用享祀」。然处二阴之中，未可往也，故「征㓙」；其困终亨，故「无咎」。象曰「中有庆也」。见得君子未尝困。</p><p>六三：困于石，据于蒺藜，入于其宫，不见其妻㓙。象曰：「据于蒺藜」，乘刚也；「入于其宫，不见其妻」，不祥也。</p><p>三阴爻本欲困君子，今乃丽于二阳之间，反为君子所困。前遇九四「困于石」也，退遇九二，「据于蒺藜」也。上六已应也，已「困于葛藟」，是「不见其妻」也。象曰「乘刚也」，谓乘九二之刚也。「不见其妻」，不祥也。系辞子曰：「非所困而困焉，名必辱；非所据而据焉，身必危。」既辱且危，死期将至，妻其可得见乎？</p><p>九四，来徐徐，困于金车，吝，有终。象曰：「来徐徐」，志在下也。虽不当位，有与也。</p><p>三阳以同德相光，几二在下，陷乎二阴之间，未能即来也，故「来徐徐」。上体兑为金，下体坎为轮，是金车也。金车可以行，处困之时，未得行也。虽「吝」，然终必相求，故「有终」。象曰：「来徐徐」，志在下也；谓九二也。虽不当位，有与也。四爻所处之位虽不当，然君子以同德相求，故「有与」。前辈谓小人无党，盖小人以利合，终必相倾；君子以理合，终必相与。</p><p>九五，劓刖，困于赤绂，乃徐有说，利用祭祀。象曰：「劓刖」，志未得也；「乃徐有说」，以中直也。「利用祭祀」，受福也。</p><p>五以阳刚处君位，乃使小人得以困君子，是谁之咎也？五威福之权在己，不过去上下之小人，则君子亨矣。「劓刖」也者，用劓刑以劓在上之小人，谓上六也；用刖刑以刖在下之小人，谓三与初也。「赤绂」，臣服。诗曰：「彼其之子，三百赤绂。」谓九二也。上下小人既去，则向者所困之赤绂乃徐徐而来，以同德而相说也。君臣同德，则必受福，故「利用祭祀」。象以君子未得志而施刑，故曰「志未得」也。九二居中而相应，故曰「以中直也」；祭必受福，故曰「受福也」。</p><p>上六：困于葛藟，于臲卼，曰动悔有悔，征吉。象曰：「困于葛藟」，未当也；「动悔有悔」，吉行也。小人扳援而据上位，犹葛藟也。然小人不宜在上，故「臲卼」不安。九五之君有施刑之志，圣人故戒之曰「动必悔」，不容幸免也。必有悔而往则吉，谓小人无故困君子，不获罪而去，则终必有聊辱之祸，故曰「动悔有悔，吉行也」。谓小人能有悔而去，是小人之福也，是以「吉行也」。䷯ 巽下坎上</p><p>井</p><p>井：改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。彖曰：巽乎水而上水，井。井养而不穷也。「改邑不改井」，乃以刚中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以凶也。</p><p>巽下坎上木上有水为井。木，井干也，辘轳之干也。汲井者，必登于木干之上，上水下木，汲之象也。邑人所居，其中有井。都邑有迁徙，而井常不移。故曰「改邑不改井，无丧无得，往来井井」。湘卿云：利物而不费，无丧也；功成而不居，无得也。来而汲，则不拒；汲而去，则不追。人有往来，而井之为井，常自若也。汲至则亦未繘井。汔，水涸也。繘，绠。当水涸而至，则未施绠而汲，汲则羸其瓶。盖井水既涸，则无以受瓶也，故「凶」。彖：「巽乎水而上水，井。」此汲井之义也。汲者以器巽乎水，然后汲而上。井道以出为功，故曰「上水，井」。井养而不穷，此言井之德，养物之功，更无穷极，惟有井之德，所以酌而不匮也。邑可改而井不可改者，以二五刚得中，惟中有定守，所以不随世变移也。当水涸而至，未能有功，是以有「羸其瓶」之「凶」也。见在二爻。</p><p>象曰：木上有水，「井」；君子以劳民劝相。</p><p>「劳民劝相」，则恩意浃洽，犹井之泽也。七月之诗，九功之歌，沐浴膏泽而歌咏劳苦，皆古人「劝相」之事也。</p><p>初六，井泥不食，旧井无禽。象曰：「井泥不食」，下也。「旧井无禽」，时舍也。</p><p>井卦六爻，刚领最好。初「井泥」，二「井谷」，皆废井也。三「井渫」，则渫初之泥；四「井甃」，则甃二之谷。泥既渫，谷既甃，则井道全矣。故五爻「井冽」而泉寒，上爻则收而「勿幕」，功用始及物，而井道大成矣。初六处最下，故为「井泥」。井水贵清而泥浊之，宜其不食，故井废而「旧禽」亦不往焉。谓失井之道，为时所弃也，故象曰「时舍也」。</p><p>九二，井谷射鲋，瓮敝漏。象曰：「井谷射鲋」，无与也。</p><p>二居初之上，而体则巽下，是井湮而为谷也。井既为谷，其水必涸，但鲋蟆相射而已。于此施绠，瓮必敝漏，盖无以受瓮也，即彖所谓「羸其瓶」是也。象曰「无与也」，谓二所以为谷者，以「无与」也。四为之甃，则有与矣。</p><p>九三，井渫不食，为我心恻，可用汲。王明，并受其福。象曰：「井渫不食」，行恻也；求「王明」，受福也。</p><p>三言「井渫」，渫初之泥也，所谓「浚井」也。井泥虽浚，人犹未食，故至者心恻然，以井泽未能及物也，虽然，亦可用汲矣。犹之人也，已德既治，有明王在上，汲而进之，则天下蒙福矣。象曰：「行恻也」，言行者见之恻然也。求「王明」，受福也。六四，井甃，无咎。象曰：「井甃无咎」，修井也。</p><p>四「井甃」，甃二之谷也，所谓修井也。谷既甃，则井之体全矣，象曰：「修井也。」初与二爻在下体，为井之地，故初「井泥」，二「井谷」。三与四居人位，必尽人事，故三「井渫」而四「井甃」，以人事言也。五与上则得之天矣，是以三才之位取义也。</p><p>九五，井洌，寒泉食。象曰：「寒泉」之食，中正也。</p><p>井至五爻，初泥已浚，二谷已修，井道已全，则井冽而泉寒，为时所食。所谓「养而不穷，往来井井」，皆在此爻。象曰：中正也。</p><p>上六：井收，勿幕，有孚，元吉。象曰：「元吉」在上，大成也。五爻井冽可食；上爻水已在木上，绠汲而水出，功用及物矣。幕，所以盖井也。井功贵出，无用幕也。泽既及物，故曰「有孚」；井道大成，故曰「元吉」。象曰：「元吉」在上，大成也。䷰ 离下兑上</p><p>革革：巳日乃孚，元亨，利贞，悔亡。彖曰：「革」，水火相息，二女同居，其志不相得，曰「革」。「巳日乃孚」，革而信之。文明以说，大亨以正，革而当，其悔乃亡。天地革而四时成，汤、武革命，顺乎天而应乎人。革之时义大矣哉！</p><p>泽上火下，泽所以潴水也，水涸而火居焉，非常之变也，其卦为「革」。唐、虞禅，夏后、殷、周继圣人以天下世其子，然不能必后世子孙之皆贤也。有圣人起而易置之，是其心也。圣人不忍天下之涂炭，乃身负犯上之名，以合天人之心，此天地之大变也，而其事见于革。文王三分天下有其二，以服事商，其事见于明夷。文王非不能革也，时未当革，圣人不敢先；时而当革，圣人不敢后。圣人不能违时，能不失时而已。文王晦其事于爻，夫子发其秘于彖。学者即彖以观爻，则「革」之义著矣。曰革，巳日乃孚。时既当革，则信于心而革之，虽圣人不敢私也。「利贞」，革以正也。有汤武之志则可，无汤武之志则乱也。悔亡。圣人举事，必得万全，事已而孚，安得有悔？彖义甚明。</p><p>象曰：泽中有火，革。君子以治历明时。</p><p>「泽而有火」，泽之变也。治历明时，所以察时之变。</p><p>初九：巩用黄牛之革。象曰：「巩用黄牛」，不可以有为也。居「革」之下，未尝革也，则固守臣节而不敢以妄动。牛革坚牣之至言，而此自固也。时未可革，汤武未尝一日有无君之心也。象曰：不可以有为也。</p><p>六二：巳日乃革之，征吉，无咎。象曰：「巳日革之」，行有嘉也。以臣革君，自此而往。「巳日」，时已至也。时既当革，则往而得吉，且「无咎」也。汤以七十里，文王以百里，天应人顺，汤武不敢辞徂征而壶浆，迎仗钺而元黄。至是惟无往，往则无敌于天下矣。象曰「行有嘉也」。</p><p>九三：征㓙贞厉，革言三就，有孚。象曰：「革言三就」，又何之矣。</p><p>三处疑地，圣人以身任天下之变，虽欲无革，不容无革。曰「征㓙贞厉」，进退皆危机也。故言必三复既信而后行之。升陑之师，必在伊尹「五就」之后，而孟津之后，亦迟于三年。观兵之余，皆「革言三就」之余也。象曰「又何之矣」，三就之后，何往不可。</p><p>九四：悔亡，有孚，改命吉。象曰：「改命」之吉，信志也。</p><p>四处下卦之上，「乾」道乃革之位也。变夏为商，变商为周，时之既至，圣人不能却其来。悔既亡，众既孚，则改命而吉矣。象曰「信志也」。汤武之革。汤武之心固自信，天下之心亦无不信，盖非利也，为匹夫匹妇复仇也。九五：大人虎变，未占有孚。象曰：「大人虎变」，其文炳也。五正君位，圣人既作，万物咸睹，天下皆利见也。然攸徂之民，室家胥庆于未来苏之前；孟津之师，八百国不期而自至。天下之孚，不在于既占之后也。故曰：「大人虎变，未占有孚。」象曰：其文炳也。</p><p>上六：君子豹变，小人革面，征㓙居贞吉。象曰：「君子豹变」，其文蔚也；「小人革面」，顺以从君也。</p><p>至此，天下咸革矣。君子自奋，以副拔擢，小人洗濯以听新政。然征伐非圣人之得已也，事已则归马放牛，载橐弓矢，示不复用。盖既革之后，不可复征也。故于既革之终，戒以征㓙居贞吉。象曰：「君子豹变」，其文蔚也；「小人革面」，顺以从君也。䷱ 巽下离上</p><p>鼎</p><p>鼎：元吉，亨。彖曰：鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。鼎，鼎象也。全卦有鼎象，初为鼎足，二三四为鼎实，五为鼎耳，上为鼎铉。巽木离火，以木巽火，又鼎之用也，故名卦以鼎。大抵圣人制器，皆有个自然之象。昔禹平水土，九牧贡金，于是象物以铸鼎，示人知所避，历代传之，以为宝器。武王克商，迁九鼎于洛邑。武王宅洛，定鼎郏鄏，卜世三十，卜年八百。及周之衰，楚子问鼎，周人假设以对，以为在德不在鼎。秦汉而下，鼎已沦亡。武帝得宝鼎于汾阴，荐告宗庙，作为诗歌，见于史册。然则鼎者，国家之重器也。圣人重易，巽下离上，已有其象，故曰「鼎」。鼎，重器也。主器必长子，故曰「元」。得鼎则昌，失鼎则亡，故曰「吉」。用以享上帝，养圣贤，可以通于神明矣，故曰「亨」。彖曰：「鼎」，象也，言卦有其象也。以木巽火，亨饪之义也。亨以享上帝，大亨以养圣贤，皆鼎之用也。下体巽，上体离，离为目，为文明，五为鼎耳，故曰「巽而耳目聪明」。六五一柔进居君位，下应九二之刚，此盖鼎实在二，鼎耳在五，二五相应，鼎道已全，故曰：「得中而应乎刚，是以元亨。」</p><p>象曰：木上有火，「鼎」；君子以正位凝命。</p><p>「正位凝命」，主器者之事也。「离」丽乎上，所以「正位」；「巽」申乎下，所以「凝命」。</p><p>初六，鼎颠趾，利出否。得妾以其子，无咎。象曰：「鼎颠趾」，未悖也；「利出否」，以从贵也。</p><p>以全卦之象言之，初为「趾」，二三四为「实」，五为「耳」，上为「铉」，全体一「鼎」象也。分上下体之象而观之，则上下体为二「鼎」。上体之鼎有耳而无足，故九四云：「鼎折足」；下体之鼎有足而无耳，故九三云：「鼎耳革。」六爻皆是取取象，故彖总言之曰「鼎象」也。初为鼎足。「趾」，足也。鼎有三足，今二而已。盖「颠」，倾也，倾则见其二而已，颠趾则倾鼎以出秽。「否」，秽也，出秽以纳新也，取新之义也。凡人纳妾，多出于夷俘贱隶，但以其子之可贵，岂计其所出之卑污也？亦弃秽取新之义也。子以主器，故于「鼎」之初言之，如是则虽「颠趾」而「无咎」矣。象曰「未悖也」，言趾非直颠也，以出秽而颠，是故鼎道未悖。「利出否」，以从贵也，妾以子贵故也。</p><p>九二，鼎有实，我仇有疾，不我能即，吉。象曰：「鼎有实」，慎所之也；「我仇有疾」，终无尤也。</p><p>二为鼎实，以刚居中，「有实」之象也。五，二之匹也。五为鼎耳，丽乎上体，不能下接，有相疾之象。然耳丽鼎上，若圯而下，则鼎亏矣。虽不我即，然终吉也。象曰：慎所之也。耳丽乎上，二为鼎实，不能上往，故曰「慎所之」。赖乎二不上往，五不下接，而鼎道全，故「终无尤」。</p><p>九三，鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。象曰：「鼎耳革」，失其义也。</p><p>三在下体之上，分上下体言之，有足而无耳，耳革则不能举以行，而「其行塞」。离为上，为雉，鼎既无耳，雉无所立，故不下食。观高宗彤日，雉升鼎耳而呜，今鼎耳既革，宜其不食也。若与上体合，阴阳相合，而鼎体全而悔散矣，故曰「方雨亏悔，终吉」。象曰「失其义也」，言耳革则失鼎之义也。</p><p>九四，鼎折足，覆公𫗧，其形渥㓙。象曰：「覆公𫗧」，信如何也！四居上体之下，分上下体而言之。有耳而无足，足既折，其𫗧必覆，不胜鼎之任也，故惭腼见乎色，而其形渥然，象曰「信如何也」。系辞曰：「德薄而位尊，知小而谋大，力小而任重，鲜不及矣。」易曰：「鼎折足，覆公𫗧，其形渥，凶。」言不胜其任也。</p><p>六五，鼎黄耳金铉，利贞。象曰：「鼎黄耳」，中以为实也。五，鼎耳也。鼎之举动在耳，五为鼎主，位得中。黄，中色也，故曰「黄耳」。铉所以举鼎而行，九居上，金铉也。五必得上，鼎体乃全，未与上合，利在乎贞，盖未可行也。象曰「中以为实也。」以黄取中义。</p><p>上九，鼎玉铉，大吉，无不利。象曰：玉铉在上，刚柔节也。上，鼎之铉。玉，和物也。鼎道贵和，得玉铉则阴阳和也，而鼎之功成矣。铉，一也，五取金铉，上取玉铉。金以刚为义，玉以和为义。五体柔，故以刚为贵；上体刚，故以和为贵。离上为火，而铉居之，金畏火而玉不畏火，故成鼎之功以玉为贵也。鼎之功成，则享帝养贤，而鼎道亨矣，故「大吉，无不利」。象曰：「刚柔节也」，言阴阳和而得刚柔之节也。西溪易说卷十，</p>',73)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
